  // Fall back to native child_process in pure ESM/CommonJS contexts
}

function executeTransformation({
  files,
  flags,
  parser,
  transformer,
  transformerArgs,
}: {
  files: Files
  flags: Flags
  parser: Parser
  transformer: string
  transformerArgs?: string[]
}) {
  const transformerPath = path.join(transformerDirectory, `${transformer}.js`)

  let args = ['-t', transformerPath].concat(files)

  const { dry } = flags

  if (dry) {
    args.push('--dry')
  }

  args.push('--ignore-pattern', 'node_modules')

  args.push('--parser', parser)
  if (parser === 'tsx') {
    args.push('--extensions=tsx,ts')
  } else if (parser === 'ts') {
    args.push('--extensions=ts')
  }

