      stdio: 'inherit',
    })
    result = {
      stderr: cpResult.error || (cpResult.status !== 0 ? new Error(`jscodeshift failed with status ${cpResult.status}`) : null),
    }
  }

  if (result.stderr) {
    throw result.stderr
  }
}

export function executeTransformations({
  files,
  flags,
  parser,
  transformers,
  transformerArgs = [],
}: {
  files: Files
  flags: Flags
  parser: Parser
  transformers: string[]
  transformerArgs?: string[]
}) {
  transformers.forEach((t) => {
    executeTransformation({
      files,
      flags,
      transformer: t,
      parser,
      transformerArgs,
    })
  })
}
```

